from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2];BASE=ROOT/'longform/onetake';OUT=BASE/'output'
t=json.loads((ROOT/'longform/content/timeline.json').read_text())
labels=['线团 → 标题环','标题环 → 支气管分叉','支气管分叉 → 面部冷刺激','脸侧曲线 → 耳轮','耳轮 → 肩臂线条','肩臂线条 → 纸张边缘','纸张折痕 → 叶脉','叶脉 → 桌面边界','桌面边界 → 汇聚成环']
transitions=[{'label':labels[i-1],'start':round(c['start']-(2.2 if c['id']=='title' else 2.7),3),'end':round(c['start']+1.05,3)} for i,c in enumerate(t['chapters']) if i]
data={'chapters':t['chapters'],'transitions':transitions}
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>先缓一缓 · 连续镜头版</title><style>*{box-sizing:border-box}body{margin:0;background:#090c13;color:#eee7dd;font:15px/1.65 -apple-system,"PingFang SC",Arial,sans-serif}main{max-width:1440px;margin:auto;padding:42px 40px 70px}h1{font-size:36px;font-weight:500;margin:10px 0}h2{font-size:20px;font-weight:500;margin:0 0 18px}.kicker{color:#b7906d;letter-spacing:4px;font-size:12px}.lead{color:#9da9b4;margin:8px 0 25px}.grid{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:32px}video{width:100%;aspect-ratio:16/9;background:#06060e;display:block}button,a{font:inherit}button{border:1px solid #35414a;color:#d9d4c9;background:#111821;border-radius:4px;padding:7px 11px;cursor:pointer}button:hover{border-color:#b7906d}button:disabled{opacity:.4;cursor:default}button[aria-pressed=true]{border-color:#c6a47e;color:#eccba2}a{color:#b9ceda;text-underline-offset:4px}button:focus-visible,a:focus-visible{outline:2px solid #c6a47e;outline-offset:4px}.toolbar{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:15px 0}.qualities{display:flex;gap:8px}.status{font-size:13px;color:#b6b7b2}#chapters{display:grid;gap:0}#chapters button{border:0;border-radius:0;border-bottom:1px solid #27323d;background:none;padding:11px 2px;text-align:left;font-size:13px;display:flex;justify-content:space-between;gap:8px}time{color:#8297a8;font-variant-numeric:tabular-nums}section{margin-top:35px;padding-top:26px;border-top:1px solid #27323d}.transitions{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.transitions button{text-align:left;padding:12px 14px}.transitions small{display:block;color:#8297a8;font-size:11px;margin-top:3px}.downloads{display:flex;flex-wrap:wrap;gap:18px}footer{margin-top:35px;color:#7b8e9c;font-size:12px}.note{color:#94a6b4;font-size:13px}#error{color:#ddb39a}@media(max-width:900px){main{padding:25px 18px}.grid{grid-template-columns:1fr}#chapters{grid-template-columns:1fr 1fr;column-gap:20px}.transitions{grid-template-columns:1fr 1fr}h1{font-size:28px}}@media(max-width:480px){.transitions{grid-template-columns:1fr}}</style><main><div class="kicker">ROOM TO BREATHE / CONTINUOUS TAKE</div><h1>先让身体缓一缓</h1><p class="lead">一条线，一次连续行进。配音、配乐和音效沿用已确认版本。</p><div class="grid"><div><video id="film" aria-label="连续镜头版视频" controls preload="metadata" poster="poster.png"></video><div class="toolbar"><div class="qualities"><button id="preview" disabled>1080p30 审片</button><button id="final" disabled>4K60 成片</button></div><span class="status" id="status">正在检查成片文件…</span></div><p id="error"></p></div><aside><h2>全片章节</h2><div id="chapters"></div></aside></div><section><h2>只看画面交接</h2><p class="note">点击播放交接前后的一小段；到段尾自动暂停。这里的九次交接在成片中属于同一次连续镜头。</p><div id="transitions" class="transitions"></div></section><section><h2>成片与制作资料</h2><div class="downloads"><a id="download-preview" hidden download>下载 1080p30</a><a id="download-final" hidden download>下载 4K60</a><a href="poster.png" download>画面封面</a><a href="../design.md">连续叙事设计</a><a href="motion-audit.json">轨迹检查记录</a><a href="../../output/review.html">查看上一版</a></div></section><footer>全部代码与素材保存在远端仓库的 longform/onetake。影片约 6 分 41 秒，字幕与声音时序不变。</footer></main><script>
const DATA=__DATA__,v=document.getElementById('film'),$=id=>document.getElementById(id);let stopAt=null,active='',duration=0;
const stamp=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');
async function exists(p){try{return(await fetch(p,{method:'HEAD',cache:'no-store'})).ok}catch{return false}}
function nav(){const parent=$('chapters');parent.replaceChildren();for(const c of DATA.chapters){const b=document.createElement('button');b.textContent=c.title;const time=document.createElement('time');time.textContent=stamp(c.start);b.append(time);b.disabled=c.start>=duration;b.onclick=()=>{stopAt=null;v.currentTime=c.start;v.focus()};parent.append(b)}const box=$('transitions');box.replaceChildren();for(const tr of DATA.transitions){const b=document.createElement('button');b.textContent=tr.label;const small=document.createElement('small');small.textContent=stamp(tr.start-.5)+' — '+stamp(tr.end+1);b.append(small);b.disabled=tr.end>=duration;b.onclick=()=>{stopAt=tr.end+1;v.currentTime=Math.max(0,tr.start-.5);v.play()};box.append(b)}}
function choose(name,file){stopAt=null;active=name;v.src=file;for(const n of ['preview','final'])$(n).setAttribute('aria-pressed',String(n===name));$('status').textContent=name==='final'?'4K60 · 完整成片':name==='preview'?'1080p30 · 完整审片版':'开头 45 秒 · 连续样段';}
v.onloadedmetadata=()=>{duration=v.duration;nav()};v.ontimeupdate=()=>{if(stopAt!==null&&v.currentTime>=stopAt){v.pause();stopAt=null}};v.onerror=()=>{$('error').textContent='视频暂时无法加载，请检查远端连接后刷新页面。'};
(async()=>{const p=await exists('film-1080p30.mp4'),f=await exists('film-4k60.mp4'),o=await exists('opening-45s.mp4');if(p){$('preview').disabled=false;$('preview').onclick=()=>choose('preview','film-1080p30.mp4');$('download-preview').href='film-1080p30.mp4';$('download-preview').hidden=false}if(f){$('final').disabled=false;$('final').onclick=()=>choose('final','film-4k60.mp4');$('download-final').href='film-4k60.mp4';$('download-final').hidden=false}if(p)choose('preview','film-1080p30.mp4');else if(f)choose('final','film-4k60.mp4');else if(o)choose('opening','opening-45s.mp4');else $('status').textContent='样段正在渲染';})();
</script></html>'''
(OUT/'review.html').write_text(page.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':'))))
print(OUT/'review.html')
